package com.example.praticum.ui.evaluation;
import android.os.Bundle;import android.view.*;import android.widget.*;import androidx.annotation.*;import androidx.fragment.app.Fragment;import androidx.lifecycle.ViewModelProvider;import androidx.recyclerview.widget.*;import com.example.praticum.R;import com.example.praticum.core.common.*;import com.example.praticum.data.entity.Evaluation;import java.util.*;
public class EvaluationHistoryFragment extends Fragment{
 private int sid=-1;private String title="";private boolean refresh;private EvaluationViewModel vm;private RecyclerView list;private TextView empty;private EvaluationHistoryAdapter adapter;
 public EvaluationHistoryFragment(){} @Nullable public View onCreateView(@NonNull LayoutInflater i,@Nullable ViewGroup c,@Nullable Bundle b){return i.inflate(R.layout.fragment_evaluation_history,c,false);}
 public void onViewCreated(@NonNull View v,@Nullable Bundle b){super.onViewCreated(v,b);Bundle a=getArguments();if(a!=null){sid=a.getInt("session_id",-1);title=a.getString("session_title","");}CommonHeaderHelper.configurerEnteteSousFenetre(v,"Historique des évaluations",title,requireActivity());vm=new ViewModelProvider(this).get(EvaluationViewModel.class);list=v.findViewById(R.id.rvEvaluationHistory);empty=v.findViewById(R.id.tvEvaluationHistoryEmpty);list.setLayoutManager(new LinearLayoutManager(requireContext()));
 adapter=new EvaluationHistoryAdapter(new EvaluationHistoryAdapter.Listener(){public void onConsult(Evaluation e){openDetail(e);}public void onEdit(Evaluation e){openEdit(e);}public void onDelete(Evaluation e){DeletionConfirmationDialog.show(requireContext(),"Supprimer cette évaluation ?","Les résultats et les équipes associés seront supprimés définitivement.",()->vm.deleteEvaluation(sid,e.getId()));}});list.setAdapter(adapter);
 vm.getSheetState().observe(getViewLifecycleOwner(),s->{if(s==null||!isAdded())return;List<EvaluationHistoryAdapter.Item> out=new ArrayList<>();for(Evaluation e:s.getEvaluations()){int n=0;double total=0;for(EvaluationViewModel.EvaluationTeamState t:s.getTeams())if(t.getTeam().getEvaluationId()==e.getId()){int m=t.getStudents().size();n+=m;total+=t.getScoreSur20()*m;}out.add(new EvaluationHistoryAdapter.Item(e,n,n==0?0:total/n));}adapter.submitList(out);list.setVisibility(out.isEmpty()?View.GONE:View.VISIBLE);empty.setVisibility(out.isEmpty()?View.VISIBLE:View.GONE);});
 vm.getOperationResult().observe(getViewLifecycleOwner(),r->{if(r==null)return;vm.clearOperationResult();if(!r.getMessage().trim().isEmpty())Toast.makeText(requireContext(),r.getMessage(),Toast.LENGTH_SHORT).show();if(!r.isSuccess()&&r.shouldCloseScreen())getParentFragmentManager().popBackStack();});if(sid<=0){getParentFragmentManager().popBackStack();return;}vm.loadSheet(sid);}
 private void openDetail(Evaluation e){EvaluationDetailFragment f=new EvaluationDetailFragment();Bundle b=new Bundle();b.putInt("session_id",sid);b.putString("session_title",title);b.putLong("evaluation_id",e.getId());f.setArguments(b);getParentFragmentManager().beginTransaction().replace(R.id.mainContainer,f).addToBackStack("evaluation_detail_"+e.getId()).commit();}
 private void openEdit(Evaluation e){EvaluationSheetFragment f=new EvaluationSheetFragment();Bundle b=new Bundle();b.putInt("session_id",sid);b.putString("session_title",title);b.putLong("evaluation_id",e.getId());f.setArguments(b);refresh=true;getParentFragmentManager().beginTransaction().replace(R.id.mainContainer,f).addToBackStack("evaluation_edit_"+e.getId()).commit();}
 public void onResume(){super.onResume();if(refresh&&vm!=null){refresh=false;vm.loadSheet(sid);}}public void onDestroyView(){list=null;empty=null;adapter=null;super.onDestroyView();}
}